class PowerMeasurementValueZero(Exception):
    """
    Raised when one of the real time measurements of power value is zero
    """
    pass


class VoltageMeasurementValueIncorrect(Exception):
    """
    Raised when one of the real time measurements of voltage is not
    within given range (47 - 57V)
    """
    pass


class NoMeasurementsFound(Exception):
    """
    Raised when no requested measurements found
    """
    pass


class MaxPowerConsumptionExceeded(Exception):
    """
    Raised when power consumption exceeds the maximum value
    """
    pass


class IncorrectCabinetTemperature(Exception):
    """
    Raised when cabinet's temperature has incorrect value
    """
    pass
